/**
 * A browser as a real one was recorded, reduced to what a profile needs.
 *
 * `browsers.ts` holds one of these per browser and is generated by
 * `scripts/import-browsers.ts` from curl-impersonate's captures, which are
 * ClientHellos and HTTP/2 openings taken from real browsers. Nothing in it is
 * written by hand, so a browser is added or corrected by importing again
 * rather than by editing numbers.
 */

import type { Http2Profile } from '../http/h2/connection';

export interface Capture {
  /** The signature file this came from, in curl-impersonate's `tests/signatures`. */
  source: string;
  /** Offered in this order. GREASE is written as `0x0a0a`. */
  ciphers: readonly number[];
  signatureSchemes: readonly number[];
  /** The supported groups open with a GREASE value. */
  greaseNamedGroup: boolean;
  /** The supported groups as captured, less the post-quantum ones we cannot make. */
  namedGroups: readonly number[];
  /**
   * Extension types in the order captured. GREASE is written as `0x0a0a` where
   * it leads and `0x1a1a` where it trails, which is how the TLS module tells
   * the empty one from the one carrying a byte.
   */
  extensions: readonly number[];
  /** Chrome shuffles its extensions on every connection, so the order above is one sample. */
  shuffled: boolean;
  alpn: readonly string[];
  /** The protocols ALPS names, when the browser sends it. */
  alps?: readonly string[] | undefined;
  /** The payload length of the GREASE ECH extension, when the browser sends one. */
  echPayload?: number | undefined;
  delegatedCredentials?: readonly number[] | undefined;
  recordSizeLimit?: number | undefined;
  http2: Http2Profile;
  /** Every header the browser sent, in its order. */
  headers: readonly (readonly [string, string])[];
  /** Computed from the capture, not from anything we send. */
  expected: { ja4: string; akamai: string };
}
